mapper.update:
UPDATE mk_referral_quota_bucket SET allocated=#{after.allocated},available=#{after.available},reserved=#{after.reserved},consumed=#{after.consumed},
  fencing_epoch=#{after.epoch},row_version=#{after.version},updated_at=#{now}
  WHERE tenant_id=#{tenant} AND campaign_id=#{campaign} AND rule_id=#{rule} AND bucket_id=#{bucket} AND fencing_epoch=#{before.epoch} AND row_version=#{before.version}

UPDATE mk_referral_subject_quota SET reserved_count=#{reserved},consumed_count=#{consumed},row_version=row_version+1,updated_at=#{now}
  WHERE tenant_id=#{tenant} AND campaign_id=#{campaign} AND rule_id=#{rule} AND beneficiary_key=#{subject} AND row_version=#{subjectVersion}
   AND #{reserved}+#{consumed}<=quota_limit
